cases.source:
throw new Error("SOURCE_MUST_NOT_EXECUTE");
class Other { selected() { return 0; } }
class Client {
  selected(value: number) {
    return value + 1;
  }
}

throw new Error("SOURCE_MUST_NOT_EXECUTE");
const api = {
  selected(value) {
    return value;
  },
  other() {}
};

throw new Error("SOURCE_MUST_NOT_EXECUTE");
const api = {
  selected: (value) => ({value}),
  other: () => 0
};

throw new Error("SOURCE_MUST_NOT_EXECUTE");
exports.selected = function(value) {
  return value;
};

throw new Error("SOURCE_MUST_NOT_EXECUTE");
module.exports = (value) => {
  return value;
};

throw new Error("SOURCE_MUST_NOT_EXECUTE");
const lookalike = `
function selected(fake) {
}
`;
function selected(value) {
  const text = `before
}
after`;
  if (value) {
    return {text};
  }
  return null;
}
function after() {}

cases.expectedText:
function selected(value) {
  const text = `before
}
after`;
  if (value) {
    return {text};
  }
  return null;
}

